/**
 * Slack Block Kit cards for human-in-the-loop tool approvals.
 */
import { isRecord } from "../../internal/is-record.js";
export const SLACK_APPROVE_ACTION_ID = "agent_serve_approve";
export const SLACK_DENY_ACTION_ID = "agent_serve_deny";
export const SLACK_AUTH_CONNECTED_ACTION_ID = "agent_serve_auth_connected";
export const SLACK_AUTH_CANCEL_ACTION_ID = "agent_serve_auth_cancel";
export function encodeApprovalActionValue(payload) {
    return JSON.stringify(payload);
}
export function parseApprovalActionValue(raw) {
    try {
        const value = JSON.parse(raw);
        if (!isRecord(value)) {
            return null;
        }
        const sessionId = value.sessionId;
        const callId = value.callId;
        if (typeof sessionId !== "string" || typeof callId !== "string") {
            return null;
        }
        if (sessionId === "" || callId === "") {
            return null;
        }
        return { sessionId, callId };
    }
    catch {
        return null;
    }
}
export function decisionFromActionId(actionId) {
    if (actionId === SLACK_APPROVE_ACTION_ID) {
        return "approve";
    }
    if (actionId === SLACK_DENY_ACTION_ID) {
        return "deny";
    }
    return null;
}
export function decisionFromAuthActionId(actionId) {
    if (actionId === SLACK_AUTH_CONNECTED_ACTION_ID) {
        return "approve";
    }
    if (actionId === SLACK_AUTH_CANCEL_ACTION_ID) {
        return "deny";
    }
    return null;
}
export function authThreadStatus(connection) {
    const prefix = "Waiting for ";
    const suffix = " auth…";
    const budget = 50 - prefix.length - suffix.length;
    const name = connection.length <= budget ? connection : `${connection.slice(0, Math.max(0, budget - 1))}…`;
    return `${prefix}${name}${suffix}`;
}
const REDACTED = "[REDACTED]";
const SENSITIVE_KEY = /(?:pass(?:word|wd)?|secret|token|api[_-]?key|authorization|credential|private[_-]?key|access[_-]?key)/i;
/** Strip likely secrets before args are shown in Slack cards. */
export function redactSensitiveValues(value) {
    if (value === null || value === undefined) {
        return value;
    }
    if (Array.isArray(value)) {
        return value.map((item) => redactSensitiveValues(item));
    }
    if (typeof value === "object") {
        const out = {};
        for (const [key, nested] of Object.entries(value)) {
            out[key] = SENSITIVE_KEY.test(key) ? REDACTED : redactSensitiveValues(nested);
        }
        return out;
    }
    return value;
}
const SLACK_FIELD_MRDKWN_MAX = 2000;
const SLACK_ARGS_LABEL = "*Args (redacted)*\n```";
/** Max arg body that fits a section `fields` mrkdwn entry (2000 chars incl. label + fences). */
const SLACK_ARGS_DISPLAY_MAX = SLACK_FIELD_MRDKWN_MAX - SLACK_ARGS_LABEL.length - "```".length - 1;
/**
 * Full redacted JSON for Slack display. Never silently truncates without
 * noting that execution still uses the complete args.
 */
export function formatArgsForSlackDisplay(value) {
    if (value === undefined || value === null) {
        return "";
    }
    const redacted = redactSensitiveValues(value);
    const text = typeof redacted === "string" ? redacted : JSON.stringify(redacted, null, 2);
    if (text.length <= SLACK_ARGS_DISPLAY_MAX) {
        return text;
    }
    const suffix = `\n(${text.length} chars total; execution uses full args)`;
    const bodyBudget = Math.max(0, SLACK_ARGS_DISPLAY_MAX - suffix.length - 1);
    const out = `${text.slice(0, bodyBudget)}…${suffix}`;
    return out.length <= SLACK_ARGS_DISPLAY_MAX ? out : out.slice(0, SLACK_ARGS_DISPLAY_MAX);
}
export function buildApprovalBlocks(args) {
    const value = encodeApprovalActionValue({
        sessionId: args.sessionId,
        callId: args.callId,
    });
    const argsText = formatArgsForSlackDisplay(args.args);
    const fields = [
        {
            type: "mrkdwn",
            text: `*Tool*\n\`${args.toolName}\``,
        },
    ];
    if (argsText !== "") {
        fields.push({
            type: "mrkdwn",
            text: `*Args (redacted)*\n\`\`\`${argsText}\`\`\``,
        });
    }
    return [
        {
            type: "header",
            text: {
                type: "plain_text",
                text: "Approval required",
                emoji: true,
            },
        },
        {
            type: "section",
            text: {
                type: "mrkdwn",
                text: "A tool call is parked until someone in this thread approves or denies it.",
            },
        },
        {
            type: "section",
            fields,
        },
        {
            type: "actions",
            block_id: `approval_${args.callId}`.slice(0, 255),
            elements: [
                {
                    type: "button",
                    action_id: SLACK_APPROVE_ACTION_ID,
                    text: { type: "plain_text", text: "Approve", emoji: true },
                    style: "primary",
                    value,
                },
                {
                    type: "button",
                    action_id: SLACK_DENY_ACTION_ID,
                    text: { type: "plain_text", text: "Deny", emoji: true },
                    style: "danger",
                    value,
                },
            ],
        },
    ];
}
export function buildAuthBlocks(args) {
    const value = encodeApprovalActionValue({
        sessionId: args.sessionId,
        callId: args.callId,
    });
    const label = args.connection.length > 20
        ? `Authorize ${args.connection.slice(0, 17)}…`
        : `Authorize ${args.connection}`;
    return [
        {
            type: "header",
            text: {
                type: "plain_text",
                text: "MCP authorization needed",
                emoji: true,
            },
        },
        {
            type: "section",
            text: {
                type: "mrkdwn",
                text: `Connect \`${args.connection}\` so \`${args.toolName}\` can continue.`,
            },
        },
        {
            type: "actions",
            block_id: `auth_${args.callId}`.slice(0, 255),
            elements: [
                {
                    type: "button",
                    text: { type: "plain_text", text: label, emoji: true },
                    url: args.authUrl,
                },
                {
                    type: "button",
                    action_id: SLACK_AUTH_CONNECTED_ACTION_ID,
                    text: { type: "plain_text", text: "Connected", emoji: true },
                    style: "primary",
                    value,
                },
                {
                    type: "button",
                    action_id: SLACK_AUTH_CANCEL_ACTION_ID,
                    text: { type: "plain_text", text: "Cancel", emoji: true },
                    style: "danger",
                    value,
                },
            ],
        },
    ];
}
export function buildResolvedAuthBlocks(args) {
    const verb = args.decision === "approve" ? "Connected" : "Cancelled";
    const by = args.byUserId === undefined || args.byUserId === "" ? "" : ` by <@${args.byUserId}>`;
    return [
        {
            type: "section",
            text: {
                type: "mrkdwn",
                text: `*${verb}*${by} — \`${args.connection}\``,
            },
        },
    ];
}
export function buildResolvedApprovalBlocks(args) {
    const verb = args.decision === "approve" ? "Approved" : "Denied";
    const by = args.byUserId === undefined || args.byUserId === "" ? "" : ` by <@${args.byUserId}>`;
    return [
        {
            type: "section",
            text: {
                type: "mrkdwn",
                text: `*${verb}*${by} — \`${args.toolName}\``,
            },
        },
    ];
}
